": "https://openalex.org/W3178738300", "doi": "https://doi.org/10.1016/j.ijinfomgt.2021.102383", "title": "Artificial intelligence in information systems research: A systematic literature review and research agenda", "publication_year": 2021, "type": "review", "cited_by_count": 784, "open_access": {"is_oa": true, "oa_status": "hybrid", "oa_url": "https://www.sciencedirect.com/science/article/pii/S0268401221000761/pdf", "any_repository_has_fulltext": true}, "primary_location": {"id": "doi:10.1016/j.ijinfomgt.2021.102383", "doi": "https://doi.org/10.1016/j.ijinfomgt.2021.102383", "is_oa": true, "landing_page_url": "https://doi.org/10.1016/j.ijinfomgt.2021.102383", "pdf_url": "https://www.sciencedirect.com/science/article/pii/S0268401221000761/pdf", "source": {"id": "https://openalex.org/S189354248", "display_name": "International Journal of Information Management", "issn_l": "0268-4012", "issn": ["0268-4012", "1873-4707"], "is_oa": false, "is_in_doaj": false, "is_core": true, "listed_in": ["abdc-a", "anvur-class-a", "anvur-scientific", "cwts-core", "fnege-2", "jufo-3", "norway-2", "poland-140", "russia-white-list-1", "vabb-shw"], "host_organization": "https://openalex.org/P4310320990", "host_organization_name": "Elsevier BV", "host_organization_lineage": ["https://openalex.org/P4310320990"], "host_organization_lineage_names": ["Elsevier BV"], "type": "journal"}, "license": "cc-by", "license_id": "https://openalex.org/licenses/cc-by", "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "International Journal of Information Management", "raw_type": "journal-article"}, "abstract": "AI has received increased attention from the information systems (IS) research community in recent years. There is, however, a growing concern that research on AI could experience a lack of cumulative building of knowledge, which has overshadowed IS research previously. This study addresses this concern, by conducting a systematic literature review of AI research in IS between 2005 and 2020. The search strategy resulted in 1877 studies, of which 98 were identified as primary studies and a synthesise of key themes that are pertinent to this study is presented. In doing so, this study makes important contributions, namely (i) an identification of the current reported business value and contributions of AI, (ii) research and practical implications on the use of AI and (iii) opportunities for future AI research in the form of a research agenda."}]", "excerpt_truncated": true, "source_sha256": "7af1e59257e0ca2723a8c5123d947fbf5d4fd652e7acb99a2d21cead84168870", "verification_required": true, "topic_domain": "unassigned_problem", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.1093/bib/bbae275", "doi:10.1016/j.ijinfomgt.2021.102383", "openalex:W4399497299", "openalex:W3178738300"], "source_candidates": ["https://doi.org/10.1093/bib/bbae275", "https://doi.org/10.1016/j.ijinfomgt.2021.102383", "https://www.sciencedirect.com/science/article/pii/S0268401221000761/pdf"], "source_candidate_identities": {}}
